CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(60) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, display_name VARCHAR(120) NOT NULL, role ENUM('admin') NOT NULL DEFAULT 'admin', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS business_settings (id TINYINT PRIMARY KEY DEFAULT 1, business_name VARCHAR(150) NOT NULL DEFAULT 'M-DAIRY', tagline VARCHAR(150) NOT NULL DEFAULT 'From Farm To Home', phone VARCHAR(30), address TEXT, cow_rate DECIMAL(10,2) NOT NULL DEFAULT 0, buffalo_rate DECIMAL(10,2) NOT NULL DEFAULT 0, CHECK (id=1));
INSERT IGNORE INTO business_settings(id) VALUES(1);
CREATE TABLE IF NOT EXISTS parties (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, party_type ENUM('customer','vendor') NOT NULL, code VARCHAR(32) NOT NULL, name VARCHAR(150) NOT NULL, phone VARCHAR(30), address TEXT, milk_type ENUM('cow','buffalo','both') NOT NULL DEFAULT 'both', schedule ENUM('morning','night','both') NOT NULL DEFAULT 'both', morning_cow_qty DECIMAL(8,2) NOT NULL DEFAULT 0, morning_buffalo_qty DECIMAL(8,2) NOT NULL DEFAULT 0, night_cow_qty DECIMAL(8,2) NOT NULL DEFAULT 0, night_buffalo_qty DECIMAL(8,2) NOT NULL DEFAULT 0, cow_rate DECIMAL(10,2) NOT NULL DEFAULT 0, buffalo_rate DECIMAL(10,2) NOT NULL DEFAULT 0, notes TEXT, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY unique_party_code (party_type,code), KEY party_list (party_type,active,name));
CREATE TABLE IF NOT EXISTS attendance (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, party_id BIGINT UNSIGNED NOT NULL, attendance_date DATE NOT NULL, status ENUM('present','absent') NOT NULL DEFAULT 'absent', morning_cow_qty DECIMAL(8,2) NOT NULL DEFAULT 0, morning_buffalo_qty DECIMAL(8,2) NOT NULL DEFAULT 0, night_cow_qty DECIMAL(8,2) NOT NULL DEFAULT 0, night_buffalo_qty DECIMAL(8,2) NOT NULL DEFAULT 0, cow_rate DECIMAL(10,2) NOT NULL DEFAULT 0, buffalo_rate DECIMAL(10,2) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY one_attendance_per_day (party_id,attendance_date), KEY attendance_date (attendance_date), CONSTRAINT fk_attendance_party FOREIGN KEY (party_id) REFERENCES parties(id));
CREATE TABLE IF NOT EXISTS bills (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, party_id BIGINT UNSIGNED NOT NULL, bill_month CHAR(7) NOT NULL, invoice_number VARCHAR(50) NOT NULL UNIQUE, total_litres DECIMAL(12,2) NOT NULL, total_amount DECIMAL(12,2) NOT NULL, paid_amount DECIMAL(12,2) NOT NULL DEFAULT 0, status ENUM('issued','part_paid','paid') NOT NULL DEFAULT 'issued', issued_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY one_bill_per_month (party_id,bill_month), CONSTRAINT fk_bill_party FOREIGN KEY (party_id) REFERENCES parties(id));
CREATE TABLE IF NOT EXISTS bill_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, bill_id BIGINT UNSIGNED NOT NULL, attendance_id BIGINT UNSIGNED NOT NULL, service_date DATE NOT NULL, cow_litres DECIMAL(8,2) NOT NULL, buffalo_litres DECIMAL(8,2) NOT NULL, cow_rate DECIMAL(10,2) NOT NULL, buffalo_rate DECIMAL(10,2) NOT NULL, line_total DECIMAL(12,2) NOT NULL, UNIQUE KEY one_line_per_attendance (bill_id,attendance_id), CONSTRAINT fk_line_bill FOREIGN KEY (bill_id) REFERENCES bills(id) ON DELETE CASCADE, CONSTRAINT fk_line_attendance FOREIGN KEY (attendance_id) REFERENCES attendance(id));
CREATE TABLE IF NOT EXISTS payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, bill_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(12,2) NOT NULL, payment_date DATE NOT NULL, method VARCHAR(40), reference VARCHAR(100), notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_payment_bill FOREIGN KEY (bill_id) REFERENCES bills(id));
